    isbn: str
    member_id: str
    borrow_date: str  # YYYY-MM-DD
    due_date: str     # YYYY-MM-DD

    def __post_init__(self):
        # validate dates format
        for field_name in ("borrow_date", "due_date"):
            date_str = getattr(self, field_name)
            try:
                datetime.strptime(date_str, "%Y-%m-%d")
