{"tool":"write_file","args":{"path":"inventory/storage.py","content":"import json
import os
from pathlib import Path
from typing import Dict, Any

# Data keys
BOOKS = "books"
MEMBERS = "members"
ACTIVE_LOANS = "active_loans"
RETURN_FEES = "return_fees"
BORROW_HISTORY = "borrow_history"


def _default_db() -> Dict[str, Any]:
    return {
        BOOKS: [],
        MEMBERS: [],
        ACTIVE_LOANS: [],
        RETURN_FEES: [],
        BORROW_HISTORY: [],
    }


def load_db(path: str) -> Dict[str, Any]:
    p = Path(path)
    if not p.exists():
        return _default_db()
    with p.open("r", encoding="utf-8") as f:
        try:
            data = json.load(f)
        except json.JSONDecodeError:
            # corrupted file, treat as empty
            return _default_db()
    # Ensure all keys present
    for key in (_default_db().keys()):
        data.setdefault(key, [])
    return data


def save_db(path: str, data: Dict[str, Any]) -> None:
    p = Path(path)
    with p.open("w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, sort_keys=True)

# Convenience wrappers

def get_books(db):
    return db[BOOKS]

def get_members(db):
    return db[MEMBERS]

def get_active_loans(db):
    return db[ACTIVE_LOANS]

def get_return_fees(db):
    return db[RETURN_FEES]

def get_borrow_history(db):
    return db[BORROW_HISTORY]
