{"tool":"write_file","args":{"path":"inventory/reports.py","content":"from collections import Counter
from datetime import datetime
from typing import Dict, List

from . import storage


def overdue_isbns(db_path: str, as_of: str) -> List[str]:
    db = storage.load_db(db_path)
    as_of_dt = datetime.strptime(as_of, "%Y-%m-%d")
    overdue = []
    for loan in storage.get_active_loans(db):
        due_dt = datetime.strptime(loan["due_date"], "%Y-%m-%d")
        if due_dt < as_of_dt:
            overdue.append(loan["isbn"])
    return sorted(set(overdue))


def total_fees_per_member(db_path: str) -> Dict[str, float]:
    db = storage.load_db(db_path)
    fees = {}
    for record in storage.get_return_fees(db):
        mid = record["member_id"]
        fees[mid] = fees.get(mid, 0.0) + record["fee"]
    return dict(sorted(fees.items()))


def most_borrowed_isbns(db_path: str, top_n: int = 5) -> List[str]:
    db = storage.load_db(db_path)
    counter = Counter()
    for loan in storage.get_borrow_history(db):
        counter[loan["isbn"]] += 1
    most_common = counter.most_common(top_n)
    return [isbn for isbn, _ in most_common]
"}}
